<template>
  <div
    id="version"
    target="_blank"
    @click="goHelp()"
    color="white"
    class="cursor-pointer row justify-center"
    style="font-size: 11px"
  >
    <p class="on-left">DocBits Version {{ app_version }}</p>
    <p v-if="$route.path.includes('setting')" class="on-right">
      API Version {{ api_version }}
    </p>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { version_link } from 'src/utils/helpLinks';
import { appsApiService } from 'src/services';
export default defineComponent({
  name: 'Footer',
  setup() {
    return {
      app_version: ref('0.0.0'),
      api_version: ref('0.0.0'),
    };
  },
  mounted: function () {
    if (process.env.APP_VUE_CURRENT_VERSION) {
      this.app_version = process.env.APP_VUE_CURRENT_VERSION
        ? process.env.APP_VUE_CURRENT_VERSION.toString()
        : '0.0.0';
    }
    this.getApiVersion();
  },
  methods: {
    async getApiVersion() {
      await appsApiService.getApiVersion().then((response) => {
        if (response.success == true) {
          this.api_version = response.version;
        }
      });
    },
    goHelp() {
      if (!version_link) {
        return;
      }
      window.open(version_link);
    },
  },
});
</script>

<style scoped></style>
